fun <T, R> List<T>.mapChecked310(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
sealed class Outcome311 {
    data class Success(val payload: String) : Outcome311()
    data object Failure : Outcome311()
}

fun describe311(outcome: Outcome311): String = when (outcome) {
    is Outcome311.Success -> outcome.payload
    Outcome311.Failure -> "failed"
}
